#!/bin/bash
set -euo pipefail
umask 077
[[ $EUID -eq 0 ]] || { echo '请用 sudo bash 执行'; exit 1; }
command -v python3 >/dev/null
exec 9>/run/football-injuries-install.lock
flock -n 9 || { echo '安装正在运行'; exit 1; }
install -d -m 700 /etc/football-injuries /var/lib/football-injuries
install -d -m 755 /opt/football-injuries
if [[ ! -s /etc/football-injuries/key ]]; then
  read -r -s -p '粘贴 API-Sports 后台的 API Key（输入不显示），然后回车：' injury_key </dev/tty
  echo
  [[ -n "$injury_key" ]] || { echo '密钥为空'; exit 1; }
  printf '%s' "$injury_key" > /etc/football-injuries/key
  unset injury_key
fi
systemctl stop football-injuries.timer football-injuries.service 2>/dev/null || true
python3 - <<'CODE'
import base64,py_compile,os
from pathlib import Path
p=Path('/opt/football-injuries/collector.py')
t=p.with_suffix('.new')
t.write_bytes(base64.b64decode(''))
py_compile.compile(str(t),doraise=True)
t.chmod(0o600)
os.replace(t,p)
CODE
cat > /etc/systemd/system/football-injuries.service <<'UNIT'
[Unit]
Description=API-Football injury collection and access check
After=network-online.target
[Service]
Type=oneshot
ExecStart=/usr/bin/python3 /opt/football-injuries/collector.py
TimeoutStartSec=120
UMask=0077
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
PrivateTmp=true
ReadWritePaths=/var/lib/football-injuries
UNIT
cat > /etc/systemd/system/football-injuries.timer <<'UNIT'
[Unit]
Description=Collect injury snapshots every six hours
[Timer]
OnBootSec=5min
OnUnitActiveSec=6h
[Install]
WantedBy=timers.target
UNIT
systemctl daemon-reload
systemctl enable --now football-injuries.timer
systemctl start --no-block football-injuries.service
echo 'INJURY_INSTALL_OK：已启动后台权限检查，有权限则采集今天和明天伤停，每6小时更新。'
echo '查看结果：journalctl -u football-injuries.service -n 10 --no-pager'
echo '采集成功标志为 state: ok 且 records 大于0；安装成功不代表免费版有数据权限。'
echo '当前阶段保存独立伤停库，尚未接入看板、比赛映射或模型，不上传公开仓库。'
